1	/**
2	 * gh.ts — thin wrappers around the `gh` CLI and `git`. The one canonical
3	 * copy shared by every script and MCP server in this repo (workflow-invoked
4	 * `src/entrypoints/machinery/**` and Atomaton-tool-invoked `src/entrypoints/tools/**`
5	 * alike) -- see build-dist.ts for how this stays true in the deployed
6	 * output despite living in one shared place at dev time.
7	 */
8	
9	export interface RunResult {
10	  code: number;
11	  stdout: string;
12	  stderr: string;
13	}
14	
15	function run(cmd: string[]): RunResult {
16	  const proc = Bun.spawnSync({
17	    cmd,
18	    stdout: "pipe",
19	    stderr: "pipe",
20	  });
21	  return {
22	    code: proc.exitCode ?? 1,
23	    stdout: proc.stdout ? proc.stdout.toString("utf8").trim() : "",
24	    stderr: proc.stderr ? proc.stderr.toString("utf8").trim() : "",
25	  };
26	}
27	
28	/**
29	 * What to invoke for `gh`, as an argv prefix.
30	 *
31	 * `gh` everywhere except a test, which points this at its fake. It is an env var
32	 * rather than a directory on PATH because PATH does not work for this on Windows: a
33	 * bare command resolves through PATHEXT, so the fake has to carry an extension, and
34	 * the only extensions Windows will run are a compiled `.exe` or a `.cmd` — which
35	 * Bun and Node refuse to pass arguments containing `"` or `|` to, on purpose, since
36	 * cmd.exe would re-parse them. Half this repository's `gh` calls carry a jq
37	 * expression, so a `.cmd` shim rejects them.
38	 *
39	 * The fake was on PATH, and on Windows it was silently never used: what ran was the
40	 * real `gh`, with the developer's own credentials, against this repository. This
41	 * removes the resolution step that made that possible rather than fixing it, because
42	 * the failure mode of getting it wrong is writing to a live repository.
43	 *
44	 * Named for what it is. This is a test seam and nothing else: it takes a script, run by
45	 * the runtime already running, so it cannot be mistaken for configuration naming where
46	 * a real installation keeps its CLI.
47	 */
48	function ghCommand(): string[] {
49	  const fake = (process.env.ATOMATON_FAKE_GH ?? "").trim();
50	  // `process.execPath`, not `"bun"`. Resolving the name has the same problem one layer
51	  // down: a Bun installed through npm is reached by `bun.cmd`, so spawning `bun` hits
52	  // the same refusal for the same arguments. The absolute path of the runtime already
53	  // running this cannot be a shim.
54	  return fake ? [process.execPath, fake] : ["gh"];
55	}
56	
57	/** Run the `gh` CLI. Inherits GH_TOKEN from the parent environment. */
58	export function gh(...args: string[]): RunResult {
59	  return run([...ghCommand(), ...args]);
60	}
