93	/**
94	 * Whether a failure came from the far end rather than from the request.
95	 *
96	 * A 404 is an answer; a 504 is the absence of one. 429 belongs here as well: it is a
97	 * request to wait, and waiting is what a retry does.
98	 */
99	export function looksTransient(result: RunResult): boolean {
100	  const text = `${result.stderr} ${result.stdout}`;
101	  // Character classes rather than shorthand: this line has lost a backslash to
102	  // tooling twice, and `5dd` compiles just as happily as the version that works.
103	  if (/HTTP (429|5[0-9][0-9])(?![0-9])/.test(text)) return true;
104	  return /(timeout|timed out|connection reset|unexpected EOF|TLS handshake|temporary failure)/i.test(text);
105	}
